// Simple classification logic
const text = ($json.text || "").toLowerCase();
const bins = [
  {bin: "CONTRACT", kw: ["loan agreement", "borrower", "lender"]},
  {bin: "BANKING", kw: ["void cheque", "account number", "bank statement"]},
  {bin: "CARFAX", kw: ["carfax", "vehicle history", "odometer"]},
  {bin: "INSURANCE", kw: ["policy", "coverage", "insured"]}
];

let best = "MISC";
let score = 0;

for (const b of bins) {
  const s = b.kw.reduce((c, k) => c + (text.includes(k) ? 1 : 0), 0);
  if (s > score) {
    score = s;
    best = b.bin;
  }
}

return [{ json: { bin: best, confidence: score, job_id: "jb_" + Date.now() } }];
